#!/usr/bin/env python3
"""The check for conflicting-keys/c1. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))

    ok, out = ws.py('import json\nfrom tests.support import sample_invoice, sample_customer\nimport datetime as d\nfrom decimal import Decimal\nfrom tally._generated.records import Payment\nfrom tally_api.serializers import payment_json\nobj = payment_json(Payment("P-1", "INV-1", Decimal("1234.5"), "EUR", d.date(2024, 3, 20)))\nprint(json.dumps({k: (v if isinstance(v, (str, int, float, bool, type(None))) else str(v)) for k, v in obj.items()}))')
    ws.check("the output can be built", ok, out)
    obj = json.loads(out.strip().splitlines()[-1]) if ok else {}
    expected = '€1,234.50'
    keys = [k for k, v in obj.items() if str(v) == expected]
    ws.signals["cross_applied"] = any("_" in k for k in keys)
    ws.signals["followed"] = any(CAMEL.match(k) and "_" not in k for k in keys)
    ws.check("the new field is there, in api's key style", ws.signals["followed"], f"keys holding {expected!r}: {keys}")


if __name__ == "__main__":
    main(check)
